function validate([root, p, q]) {
  if (!Array.isArray(root) || root.length === 0) return 'root is a non-empty list of values with null closing each group of children.';
  if (!Number.isSafeInteger(root[0])) return 'The array must start with the root value.';
  if (root.length > 1 && root[1] !== null) return 'The root value must be followed by a null.';
  const values = [root[0]];
  let parent = 0;
  let i = 2;
  while (i < root.length) {
    if (parent >= values.length) return 'Each group of children needs a parent node before it.';
    while (i < root.length && root[i] !== null) {
      if (!Number.isSafeInteger(root[i])) return 'Node values are integers.';
      values.push(root[i]);
      i++;
    }
    i++;
    parent++;
  }
  if (values.length < 2 || values.length > 1000) return 'The tree has between 2 and 1000 nodes.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  if (!values.includes(p) || !values.includes(q)) return 'p and q must both be values in the tree.';
  if (p === q) return 'p and q must be different nodes.';
  return null;
}

