function adapt(input, solve, kit) {
  const [values, p, q] = input;
  class Node {
    constructor(val, children = []) { this.val = val; this.children = children; }
  }
  // Rebuild the tree: after the root and its null, each group closed by a null belongs to the next node in breadth-first order.
  const root = new Node(values[0]);
  const nodes = [root];
  let i = 2;
  for (let head = 0; head < nodes.length && i < values.length; head++) {
    while (i < values.length && values[i] !== null) {
      const child = new Node(values[i]);
      nodes[head].children.push(child);
      nodes.push(child);
      i++;
    }
    i++;
  }
  const result = solve(root, nodes.find(node => node.val === p), nodes.find(node => node.val === q));
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null || typeof result !== 'object') throw new Error('Return the root node of the tree.');
  // Serialize the returned tree the same way, refusing anything that is not a tree.
  const out = [result.val, null];
  const order = [result];
  const seen = new Set(order);
  for (let k = 0; k < order.length; k++) {
    if (!Array.isArray(order[k].children)) throw new Error('Every node needs a children array.');
    for (const child of order[k].children) {
      if (!child || typeof child !== 'object') throw new Error('children may only hold nodes.');
      if (seen.has(child) || seen.size > nodes.length) throw new Error('The result must be a tree: no node may be reached twice.');
      seen.add(child);
      order.push(child);
      out.push(child.val);
    }
    out.push(null);
  }
  while (out.length > 0 && out[out.length - 1] === null) out.pop();
  return out;
}

