function moveSubTree(root, p, q) {
  const parent = new Map([[root, null]]);
  let qBelowP = false;

  function dfs(node, insideP) {
    if (node === q) {
      qBelowP = insideP;
    }
    for (const child of node.children) {
      parent.set(child, node);
      dfs(child, insideP || child === p);
    }
  }

  dfs(root, root === p);
  const parentOfP = parent.get(p);
  if (parentOfP === q) {
    return root;
  }
  if (qBelowP) {
    const parentOfQ = parent.get(q);
    parentOfQ.children.splice(parentOfQ.children.indexOf(q), 1);
    if (parentOfP === null) {
      root = q;
    } else {
      parentOfP.children[parentOfP.children.indexOf(p)] = q;
    }
  } else {
    parentOfP.children.splice(parentOfP.children.indexOf(p), 1);
  }
  q.children.push(p);
  return root;
}

