function moveSubTree(root, p, q) {
  // Edit plain lists of child values, then write them back onto the nodes.
  const byValue = new Map();
  const kids = new Map();
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    byValue.set(node.val, node);
    kids.set(node.val, node.children.map(child => child.val));
    for (const child of node.children) stack.push(child);
  }
  const parentOf = value => {
    for (const [owner, list] of kids) if (list.includes(value)) return owner;
    return null;
  };
  const P = p.val;
  const Q = q.val;
  let top = root.val;
  if (parentOf(P) === Q) return root;
  let below = false;
  for (let up = parentOf(Q); up !== null; up = parentOf(up)) if (up === P) below = true;
  const owner = parentOf(P);
  if (below) {
    const holder = parentOf(Q);
    kids.set(holder, kids.get(holder).filter(v => v !== Q));
    if (owner === null) top = Q;
    else kids.set(owner, kids.get(owner).map(v => (v === P ? Q : v)));
  } else {
    kids.set(owner, kids.get(owner).filter(v => v !== P));
  }
  kids.get(Q).push(P);
  for (const [value, list] of kids) byValue.get(value).children = list.map(v => byValue.get(v));
  return byValue.get(top);
}

