function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 850 + pick(100) : 2 + pick(9);
  // Unique values: a shuffled run of distinct integers.
  const pool = Array.from({ length: size === 'large' ? 2 * n : 3 * n }, (_, k) => k + 1);
  for (let k = pool.length - 1; k > 0; k--) {
    const j = pick(k + 1);
    [pool[k], pool[j]] = [pool[j], pool[k]];
  }
  const shape = rand();
  const nodes = [{ val: pool[0], children: [], parent: null }];
  while (nodes.length < n) {
    // Deep trees grow from recent nodes, wide trees from a few early ones, mixed trees from anywhere.
    let parent;
    if (shape < 0.3) parent = nodes[Math.max(0, nodes.length - 1 - pick(3))];
    else if (shape < 0.5) parent = nodes[pick(Math.min(nodes.length, 4))];
    else parent = nodes[pick(nodes.length)];
    const child = { val: pool[nodes.length], children: [], parent };
    parent.children.push(child);
    nodes.push(child);
  }
  const values = [nodes[0].val, null];
  const order = [nodes[0]];
  for (let k = 0; k < order.length; k++) {
    for (const child of order[k].children) {
      order.push(child);
      values.push(child.val);
    }
    values.push(null);
  }
  while (values[values.length - 1] === null) values.pop();
  const below = node => {
    const found = [];
    const stack = [...node.children];
    while (stack.length > 0) {
      const next = stack.pop();
      found.push(next);
      stack.push(...next.children);
    }
    return found;
  };
  const mode = rand();
  let p;
  let q;
  if (mode < 0.3) {
    const owners = nodes.filter(node => node.children.length > 0);
    p = owners[pick(owners.length)];
    const under = below(p);
    q = under[pick(under.length)];
  } else if (mode < 0.45) {
    p = nodes[1 + pick(n - 1)];
    q = p.parent;
  } else if (mode < 0.55) {
    p = nodes[0];
    q = nodes[1 + pick(n - 1)];
  } else {
    p = nodes[pick(n)];
    q = nodes[pick(n)];
    while (q === p) q = nodes[pick(n)];
  }
  return [values, p.val, q.val];
}
